// Build the Groq (Llama 3.3) prompt based on incoming action.
// Frontend sends: { action, ...payload }

const body = $input.first().json.body || $input.first().json;
const action = body.action || 'chat_response';

const prompts = {
  generate_copy: {
    system: 'You are an expert marketing copywriter. Return ONLY a JSON object of the form {"posts": [string, string, string]} with exactly 3 short post drafts. No prose, no explanation.',
    user: `Topic: ${body.topic}\nPlatform: ${body.platform}\nTone: ${body.tone}\nAudience: ${body.audience}\n\nReturn JSON {"posts":[...]} with 3 distinct post drafts.`
  },
  generate_strategy: {
    system: 'You are a senior digital strategist. Return ONLY a JSON object with this exact shape: {"overview": string, "targetAudience": string, "keyThemes": string[], "suggestedPosts": [{"platform": string, "content": string, "hashtags": string[], "bestTime": string}]}',
    user: `Product: ${body.productName}\nGoal: ${body.goal}\n\nDraft a comprehensive multi-channel campaign strategy. Include 2-4 suggested posts across LinkedIn, Twitter, Instagram, or Facebook.`
  },
  analyze_lead: {
    system: 'You are a B2B lead-scoring AI. Return ONLY a JSON object: {"score": number 0-100, "reason": short string}',
    user: `Lead: ${body.name}\nSource: ${body.source}\nInteractions: ${body.interactions}\n\nScore this lead 0-100 and explain in one short sentence.`
  },
  analyze_competitor: {
    system: 'You are a strategic analyst. Return ONLY a JSON object: {"strengths": string[], "weaknesses": string[], "opportunities": string[], "threats": string[], "strategicAdvice": string}',
    user: `Competitor: ${body.competitorName}\nIndustry: ${body.industry}\n\nProduce a SWOT analysis with 2-4 bullets per quadrant and one paragraph of strategic advice for outcompeting them.`
  },
  optimize_content: {
    system: 'You rewrite marketing copy. Return ONLY a JSON object: {"original": string, "optimized": string, "changesMade": string}',
    user: `Original: ${body.originalText}\nGoal: ${body.goal}\n\nRewrite to meet the goal. "changesMade" should be one short sentence describing what you changed.`
  },
  generate_persona: {
    system: 'You build customer personas. Return ONLY a JSON object: {"name": string, "ageRange": string, "occupation": string, "incomeLevel": string, "bio": string, "goals": string[], "frustrations": string[], "motivations": string[], "preferredChannels": string[]}',
    user: `Product: ${body.productName}\nIndustry: ${body.industry}\nRegion: ${body.region || 'Global'}\n\nBuild a detailed customer persona with realistic name, demographics, and 3-4 items for each list.`
  },
  generate_seo: {
    system: 'You are an SEO researcher. Return ONLY a JSON object: {"keywords": [{"term": string, "volume": string, "difficulty": string}], "contentIdeas": string[], "competitorUrls": string[]}',
    user: `Topic: ${body.topic}\nNiche: ${body.niche}\n\nReturn 5 keyword ideas (with rough volume estimates and difficulty High/Medium/Low), 3 content ideas, and 2 competitor URLs.`
  },
  chat_response: {
    system: 'You are Kimi, a helpful AI marketing assistant for the AutoMarketer platform. Be concise (1-3 sentences), specific, and actionable. Reply as plain text. No JSON, no markdown.',
    user: body.message || ''
  }
};

const cfg = prompts[action] || prompts.chat_response;
const expectsJson = action !== 'chat_response';

return [{
  json: {
    action,
    expectsJson,
    payload: {
      model: 'llama-3.3-70b-versatile',
      messages: [
        { role: 'system', content: cfg.system },
        { role: 'user', content: cfg.user }
      ],
      temperature: 0.7,
      max_tokens: 1500,
      ...(expectsJson ? { response_format: { type: 'json_object' } } : {})
    }
  }
}];

// Parse Groq's response into the shape the frontend expects.
// Groq returns OpenAI-compatible chat completion format.

const llmResp = $input.first().json;
const priorContext = $('Build LLM Prompt').first().json;
const action = priorContext.action;
const expectsJson = priorContext.expectsJson;

let content = llmResp.choices?.[0]?.message?.content?.trim() || '';

if (!expectsJson) {
  // chat_response — return a plain string
  return [{ json: { result: content } }];
}

// Strip markdown fences if present
const stripped = content.replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(stripped);
} catch (e) {
  const match = stripped.match(/[\[{][\s\S]+[\]}]/);
  if (match) {
    parsed = JSON.parse(match[0]);
  } else {
    throw new Error(`LLM returned non-JSON for action ${action}: ${content.slice(0, 200)}`);
  }
}

// generate_copy expects a bare array; the LLM returns {posts:[...]}. Unwrap it.
if (action === 'generate_copy') {
  if (Array.isArray(parsed)) {
    return [{ json: { result: parsed } }];
  }
  if (parsed && Array.isArray(parsed.posts)) {
    return [{ json: { result: parsed.posts } }];
  }
  throw new Error('generate_copy expected array or {posts:[]}');
}

return [{ json: { result: parsed } }];
